//! Provider seam. v3.0 ships Gemini only ([`crate::gemini`]); others plug in via
//! [`MediaProvider`] and must be added to the host allowlist in code review.

use async_trait::async_trait;

use crate::credentials::ApiKey;
use crate::types::MediaKind;

/// Raw generated bytes plus the provider's claimed mime (advisory only; the host
/// re-derives the type from magic bytes).
#[derive(Debug)]
pub struct GeneratedMedia {
    /// Decoded output bytes.
    pub bytes: Vec<u8>,
    /// Provider-claimed mime type (not trusted).
    pub claimed_mime: String,
}

/// A long-running provider operation id (validated charset, safe in a URL path).
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct OperationId(pub String);

/// Result of starting a long-running generation.
#[derive(Debug)]
pub enum SubmitOutcome {
    /// Running; poll with the id.
    Running(OperationId),
    /// The provider finished immediately.
    Done(GeneratedMedia),
}

/// One poll of a long-running operation.
#[derive(Debug)]
pub enum PollOutcome {
    /// Still running.
    Pending,
    /// Finished.
    Done(GeneratedMedia),
}

/// Provider failure classes (no provider text ever stored or surfaced).
#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum ProviderError {
    /// Safety/policy refusal or no output; closed vocabulary.
    #[error("provider refused: {0}")]
    Refused(String),
    /// Provider rate/quota limit.
    #[error("provider quota")]
    Quota,
    /// Provider-side or transport timeout.
    #[error("provider timeout")]
    Timeout,
    /// Anything else.
    #[error("provider backend: {0}")]
    Backend(String),
}

/// A generation backend.
#[async_trait]
pub trait MediaProvider: Send + Sync {
    /// Provider name for BYOK lookup (`gemini`).
    fn name(&self) -> &'static str;
    /// Synchronous image generation.
    async fn generate_image(
        &self,
        key: &ApiKey,
        prompt: &str,
    ) -> Result<GeneratedMedia, ProviderError>;
    /// Starts music/video generation.
    async fn submit(
        &self,
        kind: MediaKind,
        key: &ApiKey,
        prompt: &str,
    ) -> Result<SubmitOutcome, ProviderError>;
    /// Polls an operation started by [`Self::submit`].
    async fn poll(
        &self,
        kind: MediaKind,
        key: &ApiKey,
        op: &OperationId,
    ) -> Result<PollOutcome, ProviderError>;
}
